mapper.select:
SELECT notice_id, course_code, course_name, teacher_name, class_name, course_seq, selected_student_count, credit, scheduled_hours, offering_department, teacher_title, course_category, course_nature, course_attribute, campus, teacher_id, plan_hour_unit, group_name, scheduled_student_count, actual_class_size, is_degree_course, lecture_weeks, lab_weeks, total_plan_hours, experiment_weeks, practice_weeks, other_weeks, lecture_hours, lab_hours, experiment_hours, practice_weeks_count, arranged_hours, other_hours, weekly_hours, functional_area, confirm_status, semester_id, major FROM TEACHING_SCHEDULE
AND teacher_name LIKE CONCAT('%', #{teacherName}, '%')
AND course_name LIKE CONCAT('%', #{courseName}, '%')
AND major LIKE CONCAT('%', #{major}, '%')
AND semester_id = #{semesterId}
AND confirm_status = #{confirmStatus}

mapper.update:
UPDATE TEACHING_SCHEDULE
SET confirm_status = 1
WHERE notice_id = #{noticeId}
